    // Custom HTTP adapter
    'custom_auth_method_help' => 'Adapteri autentimisviis sinu API-s. <code>Bearer</code> saadab juurdepääsutõendi päises <code>Authorization</code>. <code>Basic</code> saadab kasutajanime ja parooli. <code>API Key</code> saadab väärtuse kohandatud päises. <code>None</code> ei saada autentimispäiseid.',
    'custom_bearer_token_help' => 'Kasutatakse autentimisviisi <code>Bearer Token</code> korral. Väärtus saadetakse päisena <code>Authorization: Bearer &lt;token&gt;</code>.',
    'custom_basic_username_help' => 'Kasutatakse autentimisviisi <code>Basic Auth</code> korral.',
    'custom_basic_password_help' => 'Kasutatakse autentimisviisi <code>Basic Auth</code> korral.',
    'custom_api_key_header_help' => 'Sinu API oodatav päisenimi, nt <code>X-API-Key</code> või <code>X-Auth-Token</code>. Kasutatakse autentimisviisi <code>API Key Header</code> korral.',
    'custom_api_key_value_help' => 'Ülal seadistatud päises saadetav väärtus.',
    'custom_pull_path_help' => 'Sisselaadimisel baas-URL-ile lisatav tee, nt <code>/api/v1/devices</code>. Baas-URL-i enda kasutamiseks jäta tühjaks.',
    'custom_records_path_help' => 'Punktidega eraldatud tee JSON-vastuses kirjete massiivini, nt <code>data.devices</code> või <code>results</code>. Jäta tühjaks, kui vastuse juur on juba massiiv.',
    'custom_source_id_path_help' => 'Kohustuslik. Punktidega tee ühes kirjes selle teenusepakkuja püsiva kordumatu ID-ni, nt <code>id</code>, <code>uuid</code> või <code>serial_number</code>. Snipe-IT kasutab seda väärtust kirjete sobitamiseks sünkroonimiste vahel, et järgmised sisselaadimised uuendaksid sama vahendit ega looks duplikaate.',
    'custom_pagination_style_help' => 'Kuidas adapter liigub teenusepakkuja esimeselt tulemuste lehelt edasi. <code>None</code> saadab ühe päringu ja lõpetab. <code>Offset + Limit</code> pärib sama lõpp-punkti parameetritega <code>?limit=X&offset=Y</code>. <code>Page Number + Limit</code> kasutab parameetreid <code>?limit=X&page=N</code> (Snipe-IT API, Laraveli tüüpi API-d). <code>Next URL</code> järgib igas vastuses tagastatud absoluutset URL-i.',
    'custom_pagination_page_size_help' => 'Ühe lehe kohta küsitav kirjete arv. Vaikimisi <code>500</code>.',
    'custom_pagination_limit_param_help' => 'Lehe suurust edastava päringuparameetri nimi, nt <code>limit</code>, <code>per_page</code> või <code>page_size</code>.',
    'custom_pagination_offset_param_help' => 'Algusnihet edastava päringuparameetri nimi, nt <code>offset</code>, <code>start</code> või <code>skip</code>.',
    'custom_pagination_page_param_help' => 'Lehenumbrit edastava päringuparameetri nimi, nt <code>page</code> või <code>p</code>.',
    'custom_pagination_page_start_help' => 'Esimese lehe number. Vaikimisi <code>1</code>. Nullist nummerdavate API-de puhul määra <code>0</code>.',
    'custom_pagination_next_path_help' => 'Punktidega eraldatud tee vastuse sisus järgmise lehe absoluutse URL-ini, nt <code>links.next</code> või <code>meta.next_page_url</code>. Kui tee väärtus on tühi või puudub, lõpetatakse lehekülgede laadimine.',
    'custom_field_paths_label' => 'Teenusepakkuja vastuse teed',
    'custom_field_paths_help' => 'Vastenda iga Snipe-IT sihtväli (tavaväli, kohandatud väli või andmebaasiveerg) punktidega teega, kus selle väärtus asub teenusepakkuja JSON-vastuse ühes kirjes. Vali sihtväli, sisesta tee (nt <code>hardware.serial</code>), vali suund (sisse, välja või mõlemad) ning lisa.',
    'field_map_column_field' => 'Snipe-IT väli',
    'field_map_column_path' => 'Teenusepakkuja punktidega tee',
